package dev.ghost;

import io.smallrye.mutiny.Uni;
import jakarta.enterprise.context.ApplicationScoped;
import org.pipelineframework.service.ReactiveService;

@ApplicationScoped
public class ChooseTurn implements ReactiveService<RunState, NextTurn> {
  public Uni<NextTurn> process(RunState r) {
    return Uni.createFrom().item(() -> transform(r));
  }

  private NextTurn transform(RunState r) {
    String end = Runs.endReason(r);
    if (!end.isEmpty()) return new NextTurn.Done(new RunResult(r, end));
    if (r.player().equals("TEV1"))
      return new NextTurn.Model(
          new ModelTurn(r, Observations.request(r.game(), r.navigation(), r.agentClues())));
    if (r.player().equals("TEV1_4B"))
      return new NextTurn.Large(
          new LargeModelTurn(r, Observations.request(r.game(), r.navigation(), r.agentClues())));
    String action =
        r.player().equals("HUMAN")
            ? r.action()
            : Baselines.choose(r.game(), r.player(), r.decisions(), r.stack());
    return new NextTurn.Action(new ActionTurn(r, action, 0));
  }
}
package dev.ghost;

import static io.restassured.RestAssured.given;
import static org.junit.jupiter.api.Assertions.*;

import io.quarkus.test.junit.QuarkusTest;
import jakarta.inject.Inject;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;

@QuarkusTest
class GhostRecordingE2ETest {
  @Inject Session session;

  private void reset(long seed, int level, boolean single) {
    given()
        .contentType("application/json")
        .body(Map.of("seed", seed, "level", level, "singleLevel", single))
        .post("/api/game")
        .then()
        .statusCode(200);
  }

  private void action(String a) {
    given()
        .contentType("application/json")
        .body(Map.of("action", a, "revision", session.latest().revision()))
        .post("/api/game/actions")
        .then()
        .statusCode(200);
  }

  private void play(String player, int limit, long millis) {
    play(player, limit, millis, false);
  }

  private void play(String player, int limit, long millis, boolean clues) {
    given()
        .contentType("application/json")
        .body(
            Map.of(
                "player",
                player,
                "revision",
                session.latest().revision(),
                "maxDecisions",
                limit,
                "durationMs",
                millis,
                "agentClues",
                clues))
        .post("/api/game/play")
        .then()
        .statusCode(200);
  }

  private void waitForPlayer() throws Exception {
    long deadline = System.nanoTime() + 125_000_000_000L;
    while (session.active() && System.nanoTime() < deadline) Thread.sleep(30);
    assertFalse(session.active());
  }

  @Test
  void ghostRecordingE2ECompletesHumanCampaignThenBoundedPlayers() throws Exception {
    reset(1983, 1, false);
    for (int level = 1; level <= 3; level++)
      for (String a : Rules.witness(session.latest().game())) action(a);
    assertEquals("WON", session.latest().game().status());
    assertEquals(3, session.latest().game().exitsFound());
    if (Boolean.getBoolean("ghost.live")) {
      reset(1983, 1, true);
      play("TEV1", 3, 40000);
      waitForPlayer();
      assertTrue(session.latest().decisions() > 0);
      assertFalse(session.frame().get("reason").toString().startsWith("PROVIDER_"));
    }
    reset(1983, 1, true);
    play("EXPLORER", 128, 120000);
    waitForPlayer();
    assertEquals("WON", session.latest().game().status());
    assertTrue(session.latest().decisions() <= 128);
    given().get("/").then().statusCode(200);
    given()
        .get("/api/game")
        .then()
        .statusCode(200)
        .body("decisionPrompt", org.hamcrest.Matchers.equalTo(Observations.PROMPT_VERSION));
  }

  @Test
  void validatesActionsOwnershipAndBounds() throws Exception {
    reset(1986, 1, true);
    given()
        .contentType("application/json")
        .body(Map.of())
        .post("/api/game/actions")
        .then()
        .statusCode(400);
    given()
        .contentType("application/json")
        .body(Map.of())
        .post("/api/game/play")
        .then()
        .statusCode(400);
    given()
        .contentType("application/json")
        .body(Map.of("action", "TELEPORT", "revision", session.latest().revision()))
        .post("/api/game/actions")
        .then()
        .statusCode(400);
    given()
        .contentType("application/json")
        .body(Map.of("action", "FORWARD", "revision", -1))
        .post("/api/game/actions")
        .then()
        .statusCode(409);
    play("EXPLORER", 1, 120000);
    waitForPlayer();
    assertEquals(1, session.latest().decisions());
    assertEquals("DECISION_LIMIT", session.frame().get("reason"));
    reset(1986, 1, true);
    play("EXPLORER", 128, 1);
    waitForPlayer();
    assertTrue(session.latest().decisions() <= 128);
    assertEquals("TIME_LIMIT", session.frame().get("reason"));
  }

  @Test
  void pauseStopsAfterAtMostOneInFlightDecision() throws Exception {
    reset(1986, 1, true);
    play("EXPLORER", 128, 120000);
    int before = session.latest().decisions();
    given()
        .contentType("application/json")
        .body(Map.of())
        .post("/api/game/pause")
        .then()
        .statusCode(200);
    waitForPlayer();
    assertTrue(session.latest().decisions() <= before + 1);
    assertEquals("PAUSED", session.frame().get("reason"));
  }

  @Test
  void canonicalMetadataContainsOneRecursiveRootAndNativeQueriesAndCommand() throws Exception {
    String contract =
        new String(
            getClass()
                .getClassLoader()
                .getResourceAsStream("META-INF/pipeline/pipeline-contract.json")
                .readAllBytes());
    assertTrue(contract.contains("Next turn"));
    assertTrue(contract.contains("Ask Tev1"));
    assertTrue(contract.contains("Publish frame"));
    assertTrue(contract.contains("play"));
  }

  @Test
  @EnabledIfSystemProperty(named = "ghost.live", matches = "true")
  void realTev1ProposesValidatedActionsWithoutRequiringEscape() throws Exception {
    for (String player : List.of("TEV1", "TEV1_4B")) {
      reset(2026, 1, true);
      play(player, 3, 40000, true);
      waitForPlayer();
      assertFalse(session.history().isEmpty());
      assertTrue(
          session.history().stream()
              .allMatch(
                  a ->
                      a.player().equals(player) && Rules.ACTIONS.contains(a.action())
                          || a.action().equals("START")));
      assertTrue(
          session.history().stream().anyMatch(a -> a.player().equals(player) && a.latencyMs() > 0));
      assertTrue(session.latest().decisions() > 0 && session.latest().decisions() <= 3);
      given()
          .get("/api/game")
          .then()
          .body(
              "model",
              org.hamcrest.Matchers.is(player.equals("TEV1") ? "tev1:0.8b" : "tev1:latest"));
      assertFalse(
          session.frame().get("reason").toString().startsWith("PROVIDER_"),
          session.frame().toString());
    }
  }
}
package dev.ghost;

import static org.junit.jupiter.api.Assertions.*;

import java.math.BigDecimal;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.pipelineframework.connector.decision.*;

class AgentSafetyTest {
  @Test
  void actionPromptIsNonemptyExplicitAndExportedAsTheActualTypedRequest() throws Exception {
    var json = new com.fasterxml.jackson.databind.ObjectMapper();
    var game = Rules.newGame(1983, 1, 1);
    var output = new LinkedHashMap<String, Object>();
    output.put("promptVersion", Observations.PROMPT_VERSION);
    for (boolean clues : List.of(false, true)) {
      var request = Observations.request(game, Signals.initial(game), clues);
      var question = request.questions().getFirst();
      assertTrue(question.instructions().contains("Apply rules top-to-bottom"));
      assertTrue(question.instructions().contains("previousAction is TURN_LEFT or TURN_RIGHT"));
      assertTrue(question.instructions().contains("current_room_visits == 1"));
      assertEquals(clues, question.instructions().contains("Signal order:"));
      var criteria = new LinkedHashMap<String, String>();
      question.criteria().forEach(c -> criteria.put(c.label(), c.description()));
      output.put(
          clues ? "on" : "off",
          Map.of(
              "state",
              json.readTree(request.stateJson()),
              "questions",
              Map.of(
                  "action",
                  Map.of(
                      "type",
                      "choice",
                      "instructions",
                      question.instructions(),
                      "criteria",
                      criteria))));
    }
    java.nio.file.Files.createDirectories(java.nio.file.Path.of("target"));
    json.writerWithDefaultPrettyPrinter()
        .writeValue(java.nio.file.Path.of("target/decision-prompts.json").toFile(), output);
  }

  @Test
  void visitSummaryIsAnExactAliasOfObservedMemory() throws Exception {
    var json = new com.fasterxml.jackson.databind.ObjectMapper();
    var game = Rules.newGame(1983, 1, 1);
    for (String action :
        List.of("START", "TURN_RIGHT", "FORWARD", "TURN_RIGHT", "TURN_RIGHT", "FORWARD")) {
      game = Rules.act(game, action);
      var state = json.readTree(Observations.request(game).stateJson());
      int visits =
          game.memory().stream()
              .filter(m -> m.room() == state.get("room").asInt())
